using System;
using System.IO;
using System.Net;
using System.Linq;
using System.Text.RegularExpressions;
using System.Diagnostics;
using System.Threading.Tasks;
using System.Collections.Generic;
namespace CodexMeter {
public sealed class ReleaseUpdate {public string Version,Url,Hash;public long Size;}
public sealed class AppUpdate {
    public const string CurrentVersion="4.0.0";public const string AssetName="CodexMeter-update-win-x64.zip";
    public readonly string Repository;public ReleaseUpdate Available;public bool Busy;public string Status="";public event Action Changed;
    readonly string root,profile;public AppUpdate(string appRoot,string data){root=appRoot;profile=data;var source=Json.Read(File.ReadAllText(Path.Combine(root,"update-source.json")));Repository=Json.Str(source,"repository");if(!Regex.IsMatch(Repository,"^[A-Za-z0-9-]+/[A-Za-z0-9_.-]+$"))throw new Exception("Invalid GitHub repository");}
    sealed class Client:WebClient {protected override WebRequest GetWebRequest(Uri uri){var r=base.GetWebRequest(uri);r.Timeout=20000;return r;}}
    Client Web(){ServicePointManager.SecurityProtocol|=SecurityProtocolType.Tls12;var client=new Client();client.Headers["User-Agent"]="CodexMeter/"+CurrentVersion;client.Headers["Accept"]="application/vnd.github+json";client.Headers["X-GitHub-Api-Version"]="2022-11-28";return client;}
    void Notify(){if(Changed!=null)Changed();}
    public static ReleaseUpdate Parse(Dictionary<string,object> release,string repo,string current){if(Convert.ToBoolean(Json.Get(release,"draft")??false)||Convert.ToBoolean(Json.Get(release,"prerelease")??false))return null;string tag=Json.Str(release,"tag_name");if(UpdatePackage.VersionOf(tag)<=UpdatePackage.VersionOf(current))return null;var assets=Json.Get(release,"assets") as System.Collections.IEnumerable;if(assets==null)return null;foreach(var row in assets){var asset=Json.Map(row);if(Json.Str(asset,"name")!=AssetName)continue;string hash=Json.Str(asset,"digest"),url=Json.Str(asset,"browser_download_url");Uri uri;long size=Convert.ToInt64(Json.Get(asset,"size")??0);if(!Regex.IsMatch(hash,"^sha256:[a-fA-F0-9]{64}$")||size<=0||size>64*1024*1024||!Uri.TryCreate(url,UriKind.Absolute,out uri)||uri.Scheme!="https"||uri.Host!="github.com"||!uri.AbsolutePath.StartsWith("/"+repo+"/releases/download/",StringComparison.Ordinal))throw new Exception("Invalid update asset");return new ReleaseUpdate{Version=tag.TrimStart('v','V'),Url=url,Hash=hash.Substring(7),Size=size};}return null;}
    public async Task Check(){if(Busy)return;Busy=true;Status="Проверка обновлений…";Notify();try{Available=await Task.Run(()=>{using(var web=Web())return Parse(Json.Read(web.DownloadString("https://api.github.com/repos/"+Repository+"/releases/latest")),Repository,CurrentVersion);});Status=Available==null?"Установлена последняя версия":"Доступно обновление";}catch(WebException e){var response=e.Response as HttpWebResponse;Status=response!=null&&response.StatusCode==HttpStatusCode.NotFound?"Обновлений пока нет":"Не удалось проверить обновления";}catch{Status="Не удалось проверить обновления";}finally{Busy=false;Notify();}}
    public async Task<string> Download(){if(Busy||Available==null)return null;Busy=true;Status="Скачивание обновления…";Notify();try{var release=Available;string cache=Path.Combine(profile,"Updates",Guid.NewGuid().ToString("N")),zip=Path.Combine(cache,"update.zip"),stage=Path.Combine(cache,"stage");Directory.CreateDirectory(cache);await Task.Run(()=>{using(var web=Web()){web.Headers.Remove("Accept");web.Headers.Remove("X-GitHub-Api-Version");web.DownloadFile(release.Url,zip);}if(new FileInfo(zip).Length!=release.Size||!string.Equals(UpdatePackage.Hash(zip),release.Hash,StringComparison.OrdinalIgnoreCase))throw new Exception("Update checksum mismatch");UpdatePackage.Extract(zip,stage,release.Version);});string helper=Path.Combine(cache,"CodexMeter.Updater.exe");File.Copy(Path.Combine(root,"CodexMeter.Updater.exe"),helper);string job=Path.Combine(cache,"job.json");File.WriteAllText(job,Json.Write(new UpdateJob{target=root,stage=stage,version=release.Version,profile=profile,processId=Process.GetCurrentProcess().Id}));Status="Установка обновления…";return job;}catch{Status="Не удалось обновить программу";return null;}finally{Busy=false;Notify();}}
    public static void Launch(string job){string helper=Path.Combine(Path.GetDirectoryName(job),"CodexMeter.Updater.exe");var task=new System.Web.Script.Serialization.JavaScriptSerializer().Deserialize<UpdateJob>(File.ReadAllText(job));bool admin=false;string probe=Path.Combine(task.target,".codexmeter-update-"+Guid.NewGuid().ToString("N"));try{using(File.Create(probe)){}File.Delete(probe);}catch(UnauthorizedAccessException){admin=true;}Process.Start(new ProcessStartInfo(helper,"\""+job+"\""){UseShellExecute=true,Verb=admin?"runas":"",WorkingDirectory=Path.GetDirectoryName(job),WindowStyle=ProcessWindowStyle.Hidden});}
}
}
